UPDATE alphafrog_agent_run_coordination c SET
    defer_reason = #{deferReason},
    next_visible_at = #{nextVisibleAt},
    updated_at = CURRENT_TIMESTAMP
WHERE c.run_id = #{runId}
  AND c.plan_generation = #{expectedPlanGeneration}
  AND c.coordination_served_round = #{expectedServedRound}

UPDATE alphafrog_agent_run_coordination SET
    dispatch_served_round = #{roundNumber},
    dispatch_missed_rounds = 0,
    updated_at = CURRENT_TIMESTAMP
WHERE run_id = #{runId}
  AND dispatch_served_round < #{roundNumber}

UPDATE alphafrog_agent_run_coordination c SET
    plan_generation = r.plan_generation,
    updated_at = CURRENT_TIMESTAMP
FROM alphafrog_agent_run r
WHERE c.run_id = #{runId}
  AND r.id = c.run_id
  AND r.plan_generation = #{planGeneration}
  AND c.plan_generation < #{planGeneration}

